(function(){"use strict";var root=document.documentElement;function syncChrome(){var head=document.querySelector(".masthead");if(head){var h=head.getBoundingClientRect().height;root.style.setProperty("--masthead-h",Math.ceil(h)+"px");root.style.setProperty("--masthead-pos",h>window.innerHeight*0.25?"relative":"sticky");}var btn=document.getElementById("ssg-search-btn");var tools=document.querySelector(".masthead-tools");if(btn&&tools&&btn.parentNode!==tools){tools.appendChild(btn);root.style.setProperty("--search-gutter","0px");}}syncChrome();window.addEventListener("resize",syncChrome,{passive:true});if(window.ResizeObserver&&document.querySelector(".masthead")){new ResizeObserver(syncChrome).observe(document.querySelector(".masthead"));}if(window.MutationObserver){var mo=new MutationObserver(function(){if(document.getElementById("ssg-search-btn")){syncChrome();mo.disconnect();}});mo.observe(document.body,{childList:true,subtree:true});setTimeout(function(){mo.disconnect();},10000);}document.addEventListener("focusin",function(event){var el=event.target;if(!el||typeof el.getBoundingClientRect!=="function")return;var head=document.querySelector(".masthead");if(!head)return;var pos=window.getComputedStyle(head).position;if(pos!=="sticky"&&pos!=="fixed")return;var clear=head.getBoundingClientRect().bottom+8;var top=el.getBoundingClientRect().top;if(top<clear)window.scrollBy(0,top-clear);});var toggle=document.getElementById("nav-toggle");var nav=document.getElementById("site-nav");if(toggle&&nav){toggle.addEventListener("click",function(){var open=nav.classList.toggle("is-open");toggle.setAttribute("aria-expanded",open?"true":"false");});}var mode=document.getElementById("mode-toggle");var state=document.getElementById("mode-state");if(!mode||!state)return;var order=["system","light","dark"];var labels={system:state.textContent.trim(),light:mode.getAttribute("data-label-light")||"Light",dark:mode.getAttribute("data-label-dark")||"Dark"};function current(){var set=root.getAttribute("data-theme");return set==="light"||set==="dark"?set:"system";}function apply(next){if(next==="system"){root.removeAttribute("data-theme");try{localStorage.removeItem("lucid-theme");}catch(e){}}else{root.setAttribute("data-theme",next);try{localStorage.setItem("lucid-theme",next);}catch(e){}}state.textContent=labels[next];}state.textContent=labels[current()];mode.addEventListener("click",function(){apply(order[(order.indexOf(current())+1)%order.length]);});})();